-- Refuse to finish if the data has any structural problem.
do $$
declare n int;
begin
  select count(*) into n from public.tariff_check;
  if n > 0 then
    raise exception 'tariff_check found % problem(s): %', n,
      (select string_agg(region_key || ' ' || start_date || ': ' || problem, '; ') from public.tariff_check);
  end if;
  if (select count(*) from public.tariff_blocks) <> 69 then raise exception 'unexpected block count'; end if;
  if (select count(*) from public.tariff_fixed_charges) <> 9 then raise exception 'unexpected fixed count'; end if;
end $$;
